<template>
  <div class="instance-detail">
    <nav class="crumbs"><router-link to="/instances">Instances</router-link><span>/</span><span class="mono">{{ short(id) }}</span></nav>
    <div v-if="error" class="notice">{{ error }} <button class="ghost" @click="load">Retry</button></div>
    <div v-if="loading" class="empty">Loading instance…</div>
    <template v-else-if="instance.id">
      <header class="instance-header"><div><div class="eyebrow">SERVICE INSTANCE</div><div class="title-row"><h1>{{ instance.service_name || instance.name || short(instance.id) }}</h1><span class="pill" :class="pillClass(instance.state)">{{ instance.state || 'unknown' }}</span></div><p class="muted mono">{{ instance.id }}</p></div><router-link :to="`/apps/${encodeURIComponent(instance.project_id || '')}`" class="subtle-link">Open service →</router-link></header>
      <div class="facts-grid"><div class="card fact"><span>Health</span><strong><i class="health-dot" :class="{ bad: instance.health_status !== 'healthy' }"></i>{{ instance.health_status || 'Not reported' }}</strong></div><div class="card fact"><span>Compute</span><strong>{{ instance.vcpus ?? '—' }} vCPU · {{ instance.mem_mib ? `${instance.mem_mib} MiB` : '—' }}</strong></div><div class="card fact"><span>Network</span><strong class="mono">{{ instance.ip_address || '—' }}</strong></div><div class="card fact"><span>Runtime</span><strong>Firecracker / KVM</strong></div></div>
      <div class="detail-grid">
        <section class="card ssh-preview"><div class="panel-head"><div><div class="eyebrow">SAFE PREVIEW</div><h2>SSH preview · simulated</h2></div><span class="demo-badge">NO NETWORK</span></div><p class="muted ssh-copy">A read-only local simulator for this instance. Commands are selected from a small allowlist; nothing is sent over SSH or executed on a host or guest.</p><div class="terminal"><div class="terminal-top"><span class="terminal-lights"><i></i><i></i><i></i></span><span>preview session · {{ short(instance.id) }}</span><span class="readonly">READ ONLY</span></div><div class="terminal-output"><div><span class="prompt">instance$</span> {{ lastCommand || 'help' }}</div><pre>{{ output }}</pre></div><div class="terminal-controls"><select v-model="command" aria-label="Select safe preview command"><option value="help">help</option><option value="uptime">uptime</option><option value="free -m">free -m</option><option value="df -h">df -h</option><option value="uname -r">uname -r</option></select><button @click="runPreview">Run preview</button></div></div><div class="allowlist-note">Allowlisted sample commands: <code>help</code>, <code>uptime</code>, <code>free -m</code>, <code>df -h</code>, <code>uname -r</code>.</div></section>
        <section class="card instance-meta"><div class="eyebrow">OPERATOR DETAILS</div><h2>Placement &amp; state</h2><dl><div><dt>Project</dt><dd>{{ instance.project_id || '—' }}</dd></div><div><dt>Node / host</dt><dd>{{ instance.server_id || instance.node_id || '—' }}</dd></div><div><dt>Started</dt><dd>{{ instance.started_at ? ago(instance.started_at) : '—' }}</dd></div><div><dt>Image</dt><dd class="mono">{{ instance.image || '—' }}</dd></div><div><dt>Agent / guest</dt><dd>Guest-agent exec is not used by this preview</dd></div></dl><router-link to="/nodes" class="subtle-link">Open Fleet →</router-link></section>
      </div>
      <div class="detail-grid lower-detail"><section class="card"><div class="panel-head"><div><h2>Recent logs</h2><p>Agent/runtime logs; not application stdout/stderr.</p></div><router-link to="/observability?tab=logs" class="subtle-link">All logs →</router-link></div><div v-if="logsError" class="panel-error" role="alert">{{ logsError }}</div><div class="log-lines" v-else-if="logs.length"><div v-for="line in logs" :key="line.id" class="mono"><time>{{ formatTime(line.reported_at) }}</time> · {{ line.level }} · {{ line.message }}</div></div><div v-else class="empty">No log records reported for this instance.</div></section><section class="card"><div class="panel-head"><div><h2>Metrics</h2><p>Host / Firecracker-process metrics; not application metrics.</p></div><router-link to="/observability?tab=metrics" class="subtle-link">All metrics →</router-link></div><div v-if="metricsError" class="panel-error" role="alert">{{ metricsError }}</div><div v-else-if="metrics.length" class="metric-list"><div v-for="metric in metrics" :key="metric.id"><span>{{ metric.name }} <small>{{ formatTime(metric.reported_at) }}</small></span><strong>{{ metric.value }} {{ metric.unit }}</strong></div></div><div v-else class="empty">No metric records reported for this instance.</div></section></div>
    </template>
    <div v-else-if="!error" class="empty">Instance not found.</div>
  </div>
</template>
<script setup>
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ago, get, pillClass } from '../lib/api.js'
const route = useRoute(), id = String(route.params.id || '')
const instance = ref({}), logs = ref([]), metrics = ref([]), error = ref(''), logsError = ref(''), metricsError = ref(''), loading = ref(true)
const command = ref('help'), lastCommand = ref(''), output = ref('Choose a read-only command above. This is a local preview; no SSH connection is opened.')
const short = (value) => String(value || '').slice(0, 12) || '—'
function formatTime(value) { const d=Date.parse(value); return Number.isNaN(d) ? '—' : new Date(d).toLocaleString() }
const commandOutput = { help: 'Read-only preview commands:\n  uptime\n  free -m\n  df -h\n  uname -r\n\nThis browser preview never opens SSH.', uptime: 'up 12 days, 4 hours · 1 user · load average: 0.42, 0.38, 0.31  [sample]', 'free -m': '              total        used        free\nMem:           1024         384         640\nSwap:             0           0           0  [sample]', 'df -h': 'Filesystem      Size  Used Avail Use% Mounted on\n/dev/vda         8G  2.1G  5.9G  27% /  [sample]', 'uname -r': '6.1.102-porter-guest  [sample]' }
function runPreview() { lastCommand.value=command.value; output.value=commandOutput[command.value] || 'Blocked: command is not on the preview allowlist.' }
async function load() {
  loading.value=true; error.value=''; logsError.value=''; metricsError.value=''
  const params=new URLSearchParams({instance_id:id,page_size:'100'})
  const from=new Date(Date.now()-24*3600000).toISOString(), to=new Date().toISOString()
  params.set('from',from); params.set('to',to)
  const [detailResult,logResult,metricResult]=await Promise.allSettled([get(`/replicas/${encodeURIComponent(id)}`),get(`/logs?${params}`),get(`/metrics?${params}`)])
  if(detailResult.status==='fulfilled') instance.value=detailResult.value?.replica || detailResult.value?.vm || detailResult.value || {}
  else error.value=detailResult.reason?.message || 'Could not load this instance.'
  if(logResult.status==='fulfilled'&&Array.isArray(logResult.value?.items)) logs.value=logResult.value.items; else { logs.value=[]; logsError.value=logResult.status==='rejected' ? (logResult.reason?.message || 'Could not load logs.') : 'The API returned an invalid logs page.' }
  if(metricResult.status==='fulfilled'&&Array.isArray(metricResult.value?.items)) metrics.value=metricResult.value.items; else { metrics.value=[]; metricsError.value=metricResult.status==='rejected' ? (metricResult.reason?.message || 'Could not load metrics.') : 'The API returned an invalid metrics page.' }
  loading.value=false
}
onMounted(load)
</script>
<style scoped>
