2px;color:#cbd6e2;font:9px/1.6 ui-monospace,"SF Mono",Menlo,monospace}.prompt{color:#78aaff}.terminal-output pre{white-space:pre-wrap;color:#8ec3a7;font:inherit;margin-top:6px}.terminal-controls{display:flex;gap:7px;padding:8px;border-top:1px solid #202934}.terminal-controls select{font-size:8px;padding:6px}.terminal-controls button{font-size:8px;white-space:nowrap;padding:6px 9px}.allowlist-note{font-size:8px;color:var(--ink3);margin-top:8px;line-height:1.55}.allowlist-note code{color:#b7c8df}.instance-meta dl{display:grid;gap:9px;margin:12px 0}.instance-meta dl>div{display:grid;grid-template-columns:80px minmax(0,1fr);gap:8px;font-size:8.5px}.instance-meta dt{color:var(--ink3)}.instance-meta dd{color:#cbd6e2;overflow-wrap:anywhere}.instance-meta .mono{font-size:8px}.lower-detail{margin-top:10px}.lower-detail>.card{padding:14px}.log-lines{margin-top:10px;max-height:180px;overflow:auto;background:#080c11;border-radius:7px;padding:9px}.log-lines>div{font-size:8px;line-height:1.65;color:#b0bdcb;border-bottom:1px solid rgba(255,255,255,.035);padding:2px 0;word-break:break-all}.log-lines time{color:var(--ink3)}.metric-list{margin-top:11px}.metric-list>div{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid var(--soft);padding:8px 0;font-size:9px}.metric-list span{color:var(--ink2)}.metric-list small{display:block;color:var(--ink3);font-size:8px;margin-top:3px}.metric-list strong{font-weight:600}.lower-detail .empty{font-size:9px;padding:18px 8px}.notice,.panel-error{margin:12px 0;color:#ff9ba5;font-size:10px}.notice button{margin-left:7px;font-size:8px}@media(max-width:850px){.facts-grid{grid-template-columns:repeat(2,1fr)}.detail-grid{grid-template-columns:1fr}}@media(max-width:560px){.instance-header{align-items:flex-start;flex-direction:column}.facts-grid{gap:7px}.fact{padding:10px}.fact strong{font-size:9px}.instance-meta dl>div{grid-template-columns:70px minmax(0,1fr)}}
</style>
